const cfgItems = $node['Config'].json?.assignments?.assignments ?? [];
const cfg = Object.fromEntries(cfgItems.map((item) => [item.name, item.value]));
const executedQueries = $items('Build Bridge SQL').length;
const reportDate = new Date().toISOString().slice(0, 10);
return [{json:{workflowName:cfg.workflowName || 'LT - Report Attribution Bridge',sourceSystem:cfg.sourceSystem || 'bridge',executedQueries,reportDate,batchId:`bridge-${reportDate}`}}];

const s = $node['Summarize Run'].json;
const q = (value) => `'${String(value ?? '').replace(/'/g, "''")}'`;
const jsonQ = (value) => q(JSON.stringify(value));
const workflowName = s.workflowName || 'LT - Report Attribution Bridge';
const sourceSystem = s.sourceSystem || 'bridge';
const reportDate = s.reportDate || new Date().toISOString().slice(0, 10);
const batchId = s.batchId || `bridge-${reportDate}`;
const runSql = `INSERT INTO report_sync_runs (
  workflow_name, source_system, report_date, batch_id, status, started_at, finished_at, row_count, error_count, retry_count, cursor_value, error_message, metadata
) VALUES (
  ${q(workflowName)},
  ${q(sourceSystem)},
  ${q(reportDate)}::date,
  ${q(batchId)},
  'completed',
  NOW(),
  NOW(),
  ${Number(s.executedQueries || 0)},
  0,
  0,
  ${q(reportDate)},
  NULL,
  ${jsonQ({ executedQueries: s.executedQueries || 0, note: 'GHL-only attribution bridge scaffold is live.' })}::jsonb
);`;
const watermarkSql = `INSERT INTO report_sync_watermarks (
  workflow_name, source_system, watermark_key, watermark_value, updated_at
) VALUES (
  ${q(workflowName)},
  ${q(sourceSystem)},
  'latest_report_date',
  ${q(reportDate)},
  NOW()
)
ON CONFLICT (workflow_name, source_system, watermark_key) DO UPDATE SET
  watermark_value = EXCLUDED.watermark_value,
  updated_at = NOW();`;
const healthSql = `INSERT INTO report_source_health (
  source_system, status, last_success_at, last_attempt_at, last_row_count, stale_after_hours, last_error, metadata, updated_at
) VALUES (
  ${q(sourceSystem)},
  'ready',
  NOW(),
  NOW(),
  ${Number(s.executedQueries || 0)},
  48,
  NULL,
  ${jsonQ({ workflowName, executedQueries: s.executedQueries || 0 })}::jsonb,
  NOW()
)
ON CONFLICT (source_system) DO UPDATE SET
  status = EXCLUDED.status,
  last_success_at = EXCLUDED.last_success_at,
  last_attempt_at = EXCLUDED.last_attempt_at,
  last_row_count = EXCLUDED.last_row_count,
  last_error = EXCLUDED.last_error,
  metadata = EXCLUDED.metadata,
  updated_at = NOW();`;
return [{json:{sql:runSql}},{json:{sql:watermarkSql}},{json:{sql:healthSql}}];

